import {FOCUSES,stories} from './stories.js';
import {REGIONS} from './data.js';
import {REGION_GROUPS} from './regions.js';
export function renderStoryPaths(s,{escape:e,won,date}){const p=stories(s),active=s.pending?.kind==='story'?s.pending:null;
 return `<section class="path-section" id="world-paths"><div class="section-heading"><div><span class="eyebrow">THE LIFE YOU CHOSE</span><h3>내 선택에서 이어지는 다음 장.</h3></div><span class="mini-label">${p.chapters.length}개의 선택 · ${p.queue.length}개의 다음 이야기</span></div><p>구매한 것과 시간을 쓰는 방식에 따라 다른 이야기를 만나요.<br>이야기 중심 모드에서는 선택 뒤 다음 사건까지 이동하며, 역사 사건은 같은 달에 먼저 보여요.</p>${active?`<div class="path-active"><div><span class="mini-label">지금 선택할 이야기</span><h4>${e(active.title)}</h4><small>${e(active.origin)}</small></div><button class="btn small" data-tab="life">이야기 선택하기 →</button></div>`:''}<div class="path-grid"><article class="path-current"><span class="mini-label">COMING FROM MY CHOICES</span><h4>${s.job?'일과 여유 사이에서':'퇴사 이후의 다른 하루'}</h4><p>${s.job?'일을 유지해도 공간과 취미에 따른 이야기는 이어져요. 자산과 생활에서 퇴사를 선택하면 휴식 이후의 장이 열립니다.':'휴식 → 나의 리듬 → 새로운 목표. 다시 일하거나 쉬는 삶을 유지하는 선택도 가능합니다.'}</p><div class="path-queue">${p.queue.length?p.queue.slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5).map(q=>`<div><span>○</span><div><b>${e(q.origin)}</b><small>${date(q.due)} 이후 · 선택할 이야기가 준비돼요</small></div></div>`).join(''):'<p>방을 꾸미거나 집·차·취미를 선택하면 후속 이야기가 준비됩니다.</p>'}</div><button class="btn secondary small" data-tab="life">나의 다음 이야기 만나기 →</button><p class="note">조건에 맞는 이야기는 각 장마다 한 번씩 나옵니다. 집이나 차를 처분하면 아직 만나지 않은 관련 이야기는 취소돼요.</p></article><article class="path-focus"><span class="mini-label">WHERE MY TIME GOES</span><h4>지금은 어떤 시간에 마음이 가나요?</h4>${FOCUSES.map(f=>`<button class="focus-choice ${p.focus===f.id?'active':''}" data-story-focus="${f.id}" aria-pressed="${p.focus===f.id}" ${s.ended?'disabled':''}><b>${e(f.name)} ${p.focus===f.id?'✓':''}</b><small>${e(f.text)}</small></button>`).join('')}<p class="note">준비된 이야기의 우선순위만 바꿉니다. 실제 근로시간·급여·건강·수명은 바꾸지 않아요. 역사 사건과 퇴사 첫 이야기는 먼저 만납니다.</p></article></div>${p.chapters.length?`<div class="path-history">${p.chapters.slice(-4).reverse().map(c=>`<article><time>${date(c.month)}</time><h4>${e(c.choice)}</h4><p>${e(c.text)}</p><small>${c.ending?'이 장의 기억 · '+e(c.ending):'다음 장으로 이어진 선택'}</small></article>`).join('')}</div>`:''}</section>`;
}
export function renderMove(s,{escape:e,won,date}){return `<section class="world-section move-section" id="world-move"><div><span class="eyebrow">A DIFFERENT PLACE, A DIFFERENT DAY</span><h3>살고 싶은 지역에서 다시 시작.</h3><p>현재 ${e(REGIONS[s.region].name)}에서 살고 있어요.<br>85개 지역 중 다른 곳으로 이사한 뒤 그 지역의 집을 골라볼 수 있습니다.</p><p class="note">자가 주택을 보유했다면 먼저 매도해야 합니다. 이사비·월세·집값은 게임 가정이고 임대 보증금은 미반영입니다. 지역만으로 삶의 만족도를 단정하지 않아요.</p></div><div class="card move-form"><label class="field" for="move-region">다음 거주 지역<select id="move-region">${REGION_GROUPS.map(g=>`<optgroup label="${e(g.name)}">${g.regions.map(id=>`<option value="${e(id)}" ${s.region===id?'selected':''}>${e(REGIONS[id].city)}</option>`).join('')}</optgroup>`).join('')}</select></label><button class="btn secondary spacer" data-move-review="true" ${s.ended||s.home?'disabled':''}>${s.home?'집 매도 후 이사할 수 있어요':'이사비와 새 월세 확인 →'}</button>${s.home?'<button class="text-button spacer" data-shop="home">보유 주택·매도 살펴보기 ↗</button>':''}<p class="note">확인창에서 비용을 보고 실행해요. 날짜는 그대로이며 이사는 월 1회입니다.</p></div></section>`;}
export function renderLifeAlbum(s,{escape:e,won,date}){const p=stories(s),ended=p.chapters.filter(c=>c.ending),months=m=>Number(m.slice(0,4))*12+Number(m.slice(5))-1,homes=(p.homes||[]).map(h=>({...h,duration:Math.max(0,months(h.to||s.month)-months(h.from))})),longest=homes.sort((a,b)=>b.duration-a.duration)[0];const moments=[...(s.lifestyle?.moments||[]).map(m=>({month:m.month,title:m.title,text:m.text})),...p.chapters.map(c=>({month:c.month,title:c.choice,text:c.text}))].sort((a,b)=>b.month.localeCompare(a.month)).slice(0,6);
 return `<section class="life-album" id="world-album"><div class="section-heading"><div><span class="eyebrow">THIS IS HOW I LIVED</span><h3>${s.ended?'내가 살아본 IF':'지금까지 살아본 IF'}</h3></div><span class="mini-label">돈으로만 설명할 수 없는 삶</span></div><div class="album-highlights"><article><small>완성한 이야기</small><b>${ended.length}개의 장</b><p>${ended.length?e(ended.at(-1).ending):'앞으로 남길 기억이 기다려요.'}</p></article><article><small>가장 오래 머문 내 집</small><b>${longest?e(longest.name):s.home?e(s.homeDetails?.name||'현재 거주 주택'):'아직 기록된 내 집이 없어요'}</b><p>${longest?`${e(REGIONS[longest.region].name)} · ${Math.floor(longest.duration/12)}년 ${longest.duration%12}개월`:s.home?'이전 저장 기록은 과거 보유 기간을 추정하지 않습니다.':'월세로 보낸 시간도 나의 삶입니다.'}</p></article><article><small>다른 지역으로의 이동</small><b>${p.moveHistory.length}번의 이사</b><p>${e(REGIONS[s.region].name)}에서의 일상</p></article></div><div class="album-moments">${moments.map(m=>`<article><time>${date(m.month)}</time><h4>${e(m.title)}</h4><p>${e(m.text)}</p></article>`).join('')}</div>${s.ended?'<button class="btn secondary spacer" data-ui="export">이 삶의 앨범과 기록 내려받기 →</button>':'<p class="note">최근 여섯 순간을 보여줍니다. 모든 이야기와 추억은 선택의 기록·백업에 남아요.</p>'}</section>`;
}
